codeExample:
// Function Declarations are fully hoisted
hello(); // Prints: "Hello World!"

function hello() {
  console.log("Hello World!");
}

// var is hoisted but NOT initialized (it is undefined)
console.log(myVar); // Prints: undefined
var myVar = 10;

// let and const are hoisted but stay in the Temporal Dead Zone
try {
  console.log(myLet);
} catch (e) {
  console.log("Error! Cannot access myLet before initialization");
}
let myLet = 20;
